package initdb

import (
	"fmt"

	"github.com/goopg/goopg/internal/executor"
)

// pgClassBootstrapRelACL is the relacl a PostgreSQL 18.3 initdb leaves on the
// bootstrap relation rel (pgClassInitdbRelACL, generated by
// scripts/gen-pg-initdb-acls.sh): setup_privileges' GRANT SELECT … TO PUBLIC
// on the catalogs and system views, REVOKEs on the sensitive ones, and the
// information_schema.sql grants. Relations PG leaves at NULL (acldefault) stay
// NULL here.
//
// goopg used to write the empty array "{}" on every row, encoded with ndim 0,
// which PG's check_acl rejects ("ACL arrays must be one-dimensional"): a
// non-superuser on a PG node could not even read pg_catalog.pg_class
// (M0149-0001g slice 12).
func pgClassBootstrapRelACL(rel nailedRel) executor.Datum {
	nsp, ok := map[uint32]string{11: "pg_catalog", pgToastNamespaceOID: "pg_toast", infoSchemaNamespaceOID: "information_schema"}[pgClassRelnamespaceFor(rel.OID)]
	if !ok {
		return executor.NullDatum
	}
	txt, ok := pgClassInitdbRelACL[nsp+"."+rel.RelName]
	if !ok {
		return executor.NullDatum
	}
	return initdbACLDatum(txt, "relacl of "+nsp+"."+rel.RelName)
}

// pgProcBootstrapACL is the proacl a PG 18.3 initdb leaves on built-in
// function oid (pgProcInitdbProACL): system_functions.sql REVOKEs EXECUTE from
// PUBLIC on the file-access, signalling and replication-control functions and
// grants some of them to pg_monitor / pg_read_all_stats. Without it, PUBLIC
// keeps EXECUTE on all of them on a PG node (M0149-0001g slice 13).
func pgProcBootstrapACL(oid uint32) executor.Datum {
	txt, ok := pgProcInitdbProACL[oid]
	if !ok {
		return executor.NullDatum
	}
	return initdbACLDatum(txt, fmt.Sprintf("proacl of function %d", oid))
}

// initdbACLDatum encodes a generated initdb ACL text ("B" = bootstrap
// superuser) as a PG-native aclitem[]. An unknown role or malformed text is a
// programming error in the generated table and panics (initdb tests catch it).
func initdbACLDatum(txt, what string) executor.Datum {
	blob, err := executor.EncodeAclItemArrayText(txt, func(role string) uint32 {
		switch role {
		case "B":
			return 10 // BOOTSTRAP_SUPERUSERID
		case "pg_monitor":
			return 3373 // ROLE_PG_MONITOR
		case "pg_read_all_stats":
			return 3375 // ROLE_PG_READ_ALL_STATS
		}
		panic(fmt.Sprintf("pg_initdb_acls_generated.go names role %q (%s); add its pg_authid.dat OID to initdbACLDatum", role, what))
	})
	if err != nil {
		panic(fmt.Sprintf("%s: %v", what, err))
	}
	return executor.NewBytesDatum(blob)
}
